import{_ as o,C as t,o as s,c as n,E as r,a2 as i}from"./chunks/framework.IIAdu7fg.js";const _=JSON.parse('{"title":"动作后读过，不等于读回了写入：一次验证评分函数的边界实验","description":"","frontmatter":{"title":"动作后读过，不等于读回了写入：一次验证评分函数的边界实验","date":"2026-10-23","column":"industry-architecture","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"动作后出现一次成功读取，是否足以在评分函数中证明此前写入已被针对同一对象确认？","research_question_en":"Does a successful read after an action establish confirmation of the preceding write to the same object at the scorer-helper boundary?","summary":"子评分的事件条件与人们赋予它的效果核验含义应逐层对齐。","sources":"https://arxiv.org/html/2610.15714v1, https://raw.githubusercontent.com/Tomry1114/Awesome-Agent-Harness-for-Healthcare/1b64350432708adfe26db60910db863ac782381d/HARNESS_DESIGN.md, https://raw.githubusercontent.com/Tomry1114/Awesome-Agent-Harness-for-Healthcare/1b64350432708adfe26db60910db863ac782381d/runner/scorers/dim_verification.py, https://raw.githubusercontent.com/Tomry1114/Awesome-Agent-Harness-for-Healthcare/1b64350432708adfe26db60910db863ac782381d/runner/scorers/governance.py, https://raw.githubusercontent.com/Tomry1114/Awesome-Agent-Harness-for-Healthcare/1b64350432708adfe26db60910db863ac782381d/runner/tests/test_verify_effect.py, https://raw.githubusercontent.com/Tomry1114/Awesome-Agent-Harness-for-Healthcare/1b64350432708adfe26db60910db863ac782381d/TASK_MANIFEST.json","pageClass":"runtime-v6-article","item_id":"SIG-20261023-004","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-23-sig-20261023-004-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-10-23-sig-20261023-004.md","filePath":"zh/industry/2026-10-23-sig-20261023-004.md","lastUpdated":1792763845000}'),c={name:"zh/industry/2026-10-23-sig-20261023-004.md"};function l(h,e,p,b,m,u){const a=t("ArticleCover"),d=t("ArticleTableScroll");return s(),n("div",null,[r(a,{image:"/assets/covers/daily-2026-10-23-sig-20261023-004-cover.png",kicker:"研究成果",title:"动作后读过，不等于读回了写入：一次验证评分函数的边界实验",summary:"子评分的事件条件与人们赋予它的效果核验含义应逐层对齐。",version:"2026-10-23",languageHref:"/en/industry/2026-10-23-sig-20261023-004",languageLabel:"English"}),r(d,{language:"zh"}),e[0]||(e[0]=i('<h1 id="动作后读过-不等于读回了写入-一次验证评分函数的边界实验" tabindex="-1">动作后读过，不等于读回了写入：一次验证评分函数的边界实验 <a class="header-anchor" href="#动作后读过-不等于读回了写入-一次验证评分函数的边界实验" aria-label="Permalink to &quot;动作后读过，不等于读回了写入：一次验证评分函数的边界实验&quot;">​</a></h1><p>一次写入之后，读取另一个对象，也能在被测评分函数中得到满额确认。这是本轮内部隔离实验的结果，不是已确认的原生系统事故。它提出的问题很具体：一个“写后确认”分数，究竟检查了时间先后，还是检查了同一写入的效果？</p><h2 id="十个场景检验的是哪一层" tabindex="-1">十个场景检验的是哪一层 <a class="header-anchor" href="#十个场景检验的是哪一层" aria-label="Permalink to &quot;十个场景检验的是哪一层&quot;">​</a></h2><p>本轮分析从固定版本的 MedHarnessBench（医疗智能体运行框架评测）源码中提取未改动的辅助函数，用构造的语义事件执行十个场景。固定版本为 <code>1b64350432708adfe26db60910db863ac782381d</code>；这项内部实验绕过原始轨迹适配器、模型和完整评分管线，没有重跑论文基准。</p><p>被测的 <code>_postcondition_confirmation</code>（后置条件确认函数）先判断任务是否要求改变状态，再遍历成功提交，寻找其后的成功读取或核验事件。判据接受进展标记，或者非空的状态变化字段。它在这一层没有比较主体、资源或提交标识。<a href="https://github.com/Tomry1114/Awesome-Agent-Harness-for-Healthcare/blob/1b64350432708adfe26db60910db863ac782381d/runner/scorers/dim_verification.py" target="_blank" rel="noreferrer">固定版本评分源码</a></p><p>下表全部是本次内部实验观测，分数只属于这个辅助函数，不代表总体评分：</p><table tabindex="0"><thead><tr><th>构造输入</th><th>辅助函数结果</th><th>这一结果说明什么</th></tr></thead><tbody><tr><td>写入后读取同一资源</td><td>1，确认一次</td><td>正常正对照可计分</td></tr><tr><td>无读取、读取失败、读取先于写入</td><td>各为0</td><td>时间与成功条件确实参与判断</td></tr><tr><td>要求写入但没有提交</td><td>0</td><td>空轨迹没有被算作完成</td></tr><tr><td>任务没有状态变化义务</td><td>不适用</td><td>不适用不能与零分合并</td></tr><tr><td>写入甲后成功读取乙</td><td>1，确认一次</td><td>此函数未约束同一对象</td></tr><tr><td>核验成功但状态变化字段为假</td><td>1</td><td>字段存在与字段为真不同</td></tr><tr><td>两次提交后一次无关读取</td><td>1，确认两次</td><td>同一读取可被两次提交复用</td></tr><tr><td>成功读取但没有上述标记</td><td>0</td><td>仅有成功事件还不够</td></tr></tbody></table><p>十个场景包含三个需要收窄解释的确认路径和七个正常或否定对照。完整输入、结果与提取绑定保存在本次研究证据包；它们不是真实患者记录。</p><h2 id="满分没有提供对象关联" tabindex="-1">满分没有提供对象关联 <a class="header-anchor" href="#满分没有提供对象关联" aria-label="Permalink to &quot;满分没有提供对象关联&quot;">​</a></h2><p>研究解释是：时间关系可以支持“随后出现过读取”，却不能单独支持“这次读取确认了那次写入”。尤其是两次提交共用一次无关读取的场景，揭示的不只是对象身份缺口，还包括确认材料是否可复用的问题。这不意味着读取必须永远只能使用一次；它意味着逐效果确认的声明需要说明关联规则和复用语义。</p><p>状态变化字段为假的场景也不能简写成“系统把失败算成成功”。事件本身被构造成成功核验，函数检查的是字段是否非空。当前证据支持的判断仅是：字段存在性与状态变化真实性不能在解释分数时混为一谈。</p><p>这种区分对过程评估有实际价值。<a href="https://arxiv.org/html/2610.15714v1" target="_blank" rel="noreferrer">论文第一版</a>的作者报告，某一健康行政任务配置中，三次机会内通过率从0.267降至0.105，而子任务分从0.543升至0.633。这里引用的是作者结果，本轮没有重算；它只用于说明终局结果和过程指标应分开阅读，不能用本轮函数实验解释这些总体数值变化。</p><h2 id="适配器可能已经承担了这项保证" tabindex="-1">适配器可能已经承担了这项保证 <a class="header-anchor" href="#适配器可能已经承担了这项保证" aria-label="Permalink to &quot;适配器可能已经承担了这项保证&quot;">​</a></h2><p>最有力的反解释是：原始轨迹转成语义事件之前，适配器可能已确保对象一致性，或者其他维度会扣除无关读取的收益。若这一不变量确实存在，函数不重复检查可能是合理的职责分配。本轮没有执行从原始轨迹到适配器、再到总分的链路，因此没有排除这种解释。</p><p>原仓库设计还区分动作前、结果后和最终答复前的检查，并保留证据、义务与提交账本。这是公开设计材料，不是已经运行的端到端保证。<a href="https://github.com/Tomry1114/Awesome-Agent-Harness-for-Healthcare/blob/1b64350432708adfe26db60910db863ac782381d/HARNESS_DESIGN.md" target="_blank" rel="noreferrer">设计文档</a></p><p>对过程评分的工程含义因此是一个责任问题：报告应写明对象关联由谁保证、哪些事件适用、无数据如何处理，以及确认材料能否被复用。若要宣称逐效果核验，就需要可审计的写入与读取关联。这个要求不等于本轮已经证明哪一层必须修改。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文把公开源码和设计当作可核查的一手材料；项目自己的公开仓库不是独立验证。十个构造场景属于本研究方的内部实验依据；上文的责任划分属于研究解释。没有独立第三方复现被用来支持函数层结论。</p><p>源码版本与论文原始实验版本的完整对应关系尚未建立。论文发表、代码可访问或实现能够执行，都不能自动扩展为总体可靠性、临床安全或普遍有效性。主要材料是上述固定版本评分源码、设计文档及论文第一版；本地实验日期为2026-10-23。</p><h2 id="尚缺的端到端证据" tabindex="-1">尚缺的端到端证据 <a class="header-anchor" href="#尚缺的端到端证据" aria-label="Permalink to &quot;尚缺的端到端证据&quot;">​</a></h2><p>下一项能够改变判断的证据，是原生有效轨迹确实产生了这种无关读取事件，并且能跟踪它经过其他维度和聚合过程后的结果。在此之前，不估计受影响样本比例，不推断模型排名变化，也不声称已经发现患者混淆事故。当前可以确定的边界只在这个函数：它检查后续合格事件，本身没有建立逐对象的效果关联。</p>',21))])}const g=o(c,[["render",l]]);export{_ as __pageData,g as default};
